import express from "express";

export const app = express();

app.use(function onError(error: Error, request: express.Request, response: express.Response, next: express.NextFunction) {
    response.status(500).json({ error: error.message });
});

app.post("/products", function createProduct(request, response) {
    const body = request.body as { name?: unknown };
    if (typeof body.name !== "string") {
        response.status(400).json({ error: "invalid_name" });
        return;
    }
    response.status(201).json(body);
});

app.use(express.json());
